MIN_KEYWORDS, MAX_KEYWORDS, KEYWORD_WORDS = (2, 5, 4)
PROMPT = f'You are the doctor at the start of an encounter. For your own notes, name the kind of presentation in standard clinical terms. complaint: the main complaint or reason for the visit with its body site, one to {KEYWORD_WORDS} words, without side or duration. context: one to {MAX_KEYWORDS - 1} keywords for whatever in the opening statement narrows it, such as the age group, pregnancy, an injury, the setting or the time course; each one to {KEYWORD_WORDS} words. Describe only what the statement says and do not guess a diagnosis. Do not use digits; give an age as an age group such as child, adolescent, adult or older adult. Return ONLY {{"complaint":"...","context":["...","..."]}}.'
